package net.officefloor.hq.app;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionSynchronization;
import org.springframework.transaction.support.TransactionSynchronizationManager;

/**
 * Audit sink: appends one record per line to a KNOWN FILE (app.audit.file, default .run/audit.log)
 * so tests can assert side-effects by reading that file — the second test-assertion channel
 * alongside the UI. The file path + one-record-per-line format is a stable contract, like
 * data-testid: features may be rewritten as long as they keep emitting the agreed records.
 *
 * Inject this bean into any feature that must record an audit entry. Each write flushes (append +
 * SYNC) so a test reads the record immediately.
 */
@Service
public class Audit {

    private final Path file;

    public Audit(@Value("${app.audit.file:.run/audit.log}") String path) {
        this.file = Path.of(path);
    }

    /** Append one audit record. Tests assert the exact line(s) in the file. */
    public synchronized void record(String entry) {
        try {
            Path parent = file.toAbsolutePath().getParent();
            if (parent != null) {
                Files.createDirectories(parent);
            }
            Files.writeString(file, entry + System.lineSeparator(), StandardCharsets.UTF_8,
                    StandardOpenOption.CREATE, StandardOpenOption.APPEND, StandardOpenOption.SYNC);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }

    /**
     * Append one audit record once the current transaction commits, so a change that is refused or
     * rolled back writes nothing; outside a transaction it is appended at once.
     */
    public void recordOnCommit(String entry) {
        if (!TransactionSynchronizationManager.isSynchronizationActive()) {
            record(entry);
            return;
        }
        TransactionSynchronizationManager.registerSynchronization(new TransactionSynchronization() {
            @Override
            public void afterCommit() {
                record(entry);
            }
        });
    }

    /** Truncate the audit file. */
    public synchronized void clear() {
        try {
            Files.deleteIfExists(file);
        } catch (IOException e) {
            throw new UncheckedIOException(e);
        }
    }
}
package net.officefloor.hq.app;

import java.net.URLDecoder;
import java.nio.charset.StandardCharsets;

/**
 * Who is signed in: the screen sends the typed name with every request in the {@link #HEADER}
 * header, URI-encoded (a header carries only plain ASCII). The audit records it as the change's
 * author.
 */
public final class SignedInUser {

    public static final String HEADER = "X-User";

    private SignedInUser() {
    }

    /** The signed-in user's name from the header's value. */
    public static String decode(String header) {
        return URLDecoder.decode(header, StandardCharsets.UTF_8).trim();
    }
}
package net.officefloor.hq.app.person;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.SignedInUser;
import net.officefloor.hq.app.rollup.RollupService;
import net.officefloor.hq.app.sheet.SheetService;
import net.officefloor.hq.app.statement.StatementService;
import net.officefloor.hq.app.statement.StatementSummary;
import java.util.NoSuchElementException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.orm.ObjectOptimisticLockingFailureException;
import org.springframework.validation.annotation.Validated;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.ResponseStatus;
import org.springframework.web.bind.annotation.RestController;

@RestController
@Validated
@RequestMapping("/api/sheets/{sheetId}/people")
public class PersonController {

    /** A grade a person was given and the date it applies from (null: from the beginning of time). */
    public record GradeView(String grade, LocalDate from) {
        public static GradeView of(PersonGrade grade) {
            return new GradeView(grade.getGrade(), grade.getFrom());
        }
    }

    /** A hold put on a person: from its from-date to its to-date (null: it does not end). */
    public record HoldView(LocalDate from, LocalDate to) {
        public static HoldView of(PersonHold hold) {
            return new HoldView(hold.getFrom(), hold.getTo());
        }
    }

    /** A person as the screen shows them, with the grade in force on the sheet's today and every
     *  grade they were given from the earliest, how many statements were taken for them and the
     *  last one's due-total and date (null when none was), and whether they are retired and from
     *  when (null when not), and the holds put on them in the order they were, and the ids of their patrons in the order
     *  they were named. */
    public record PersonView(Long id, String name, String grade, List<GradeView> grades, long version,
            int statementCount, String statedTotal, LocalDate statementDate, boolean retired, LocalDate retiredFrom,
            List<HoldView> holds, List<Long> patronIds) {
        public static PersonView of(Person person, List<PersonGrade> grades, LocalDate today,
                StatementSummary statements, List<PersonHold> holds, List<Long> patronIds) {
            return new PersonView(person.getId(), person.getName(), PersonGradeService.gradeOn(grades, today),
                    grades.stream().map(GradeView::of).toList(), person.getVersion(), statements.count(),
                    statements.lastDueTotal(), statements.lastDate(), person.isRetired(), person.getRetiredFrom(),
                    holds.stream().map(HoldView::of).toList(), patronIds);
        }
    }

    /** A person's fields: a name that is not blank and a grade of A, B or C. */
    public record PersonRequest(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade) {
    }

    /** A person's fields as saved from an editor: the grade applies from its from-date (blank takes
     *  the sheet's today), with the version of the person the editor loaded. */
    public record PersonUpdate(
            @NotBlank @Size(max = 200) String name,
            @NotNull @Pattern(regexp = "[ABC]") String grade,
            LocalDate gradeFrom,
            @NotNull Long version) {
    }

    /** A retirement: the date the person is retired from (blank takes the sheet's today). */
    public record RetireRequest(LocalDate from) {
    }

    /** A hold: the date it runs from (blank takes the sheet's today) and an optional to-date. */
    public record HoldRequest(LocalDate from, LocalDate to) {
    }

    /** A patron to name: the id of another person on the sheet. */
    public record PatronRequest(@NotNull Long patronId) {
    }

    private final PersonService service;
    private final StatementService statements;
    private final RollupService rollups;
    private final PersonGradeService grades;
    private final SheetService sheets;

    public PersonController(PersonService service, StatementService statements, RollupService rollups,
            PersonGradeService grades, SheetService sheets) {
        this.service = service;
        this.statements = statements;
        this.rollups = rollups;
        this.grades = grades;
        this.sheets = sheets;
    }

    /** The sheet's people in the order they were added. */
    @GetMapping
    public List<PersonView> list(@PathVariable @NotBlank @Size(max = 200) String sheetId) {
        String sheet = sheetId.trim();
        Map<Long, StatementSummary> summaries = statements.summaries(sheet);
        Map<Long, List<Long>> patrons = service.patronIds(sheet);
        Map<Long, List<PersonGrade>> given = grades.bySheet(sheet);
        Map<Long, List<PersonHold>> holds = service.holds(sheet);
        LocalDate today = sheets.today(sheet);
        return service.list(sheet).stream()
                .map(p -> PersonView.of(p, given.getOrDefault(p.getId(), List.of()), today,
                        summaries.getOrDefault(p.getId(), StatementSummary.NONE),
                        holds.getOrDefault(p.getId(), List.of()),
                        patrons.getOrDefault(p.getId(), List.of())))
                .toList();
    }

    /** Add a person to the sheet. */
    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PersonView add(@PathVariable @NotBlank @Size(max = 200) String sheetId,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PersonRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(rollups.track(sheet, by, () -> service.add(sheet, by, request.name(),
                request.grade())));
    }

    /** Change a person's name and give them a grade from a date; refused when the person was saved since the editor loaded them. */
    @PutMapping("/{id}")
    public PersonView update(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PersonUpdate request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(rollups.track(sheet, by, () -> service.update(sheet, by, id, request.version(),
                request.name(), request.grade(), request.gradeFrom())));
    }

    /** Retire a person from a date. */
    @PostMapping("/{id}/retire")
    public PersonView retire(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody RetireRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(service.retire(sheet, by, id, request.from()));
    }

    /** Put a hold on a person from a date to an optional to-date. */
    @PostMapping("/{id}/hold")
    public PersonView hold(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody HoldRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(rollups.track(sheet, by,
                () -> service.hold(sheet, by, id, request.from(), request.to())));
    }

    /** Name another person on the sheet as a person's patron. */
    @PostMapping("/{id}/patrons")
    public PersonView addPatron(@PathVariable @NotBlank @Size(max = 200) String sheetId, @PathVariable Long id,
            @RequestHeader(SignedInUser.HEADER) @NotBlank String user, @RequestBody @Validated PatronRequest request) {
        String sheet = sheetId.trim();
        String by = SignedInUser.decode(user);
        return withStatements(service.addPatron(sheet, by, id, request.patronId()));
    }

    /** A date that is not a real yyyy-mm-dd date, or a hold that ends before it starts, is refused. */
    @ExceptionHandler({HttpMessageNotReadableException.class, HoldRefusedException.class})
    @ResponseStatus(HttpStatus.BAD_REQUEST)
    public void unreadable() {
    }

    /** Someone else saved the person since the editor loaded them: the person as stored now. */
    @ExceptionHandler(StalePersonException.class)
    @ResponseStatus(HttpStatus.PRECONDITION_FAILED)
    public PersonView stale(StalePersonException e) {
        return withStatements(e.getCurrent());
    }

    private PersonView withStatements(Person person) {
        return PersonView.of(person, grades.of(person.getId()), sheets.today(person.getSheetId()),
                statements.summary(person.getSheetId(), person.getId()), service.holds(person.getId()),
                service.patronIds(person.getId()));
    }

    /** A save that raced another to the same version; the editor re-reads the person. */
    @ExceptionHandler(ObjectOptimisticLockingFailureException.class)
    @ResponseStatus(HttpStatus.PRECONDITION_FAILED)
    public void raced() {
    }

    @ExceptionHandler(NoSuchElementException.class)
    @ResponseStatus(HttpStatus.NOT_FOUND)
    public void notFound() {
    }

    /** The name is already in use on the sheet, or the patron may not be named; a concurrent save is
     *  caught by the unique index. */
    @ExceptionHandler({NameInUseException.class, PatronRefusedException.class, DataIntegrityViolationException.class})
    @ResponseStatus(HttpStatus.CONFLICT)
    public void nameInUse() {
    }
}
package net.officefloor.hq.app.person;

import jakarta.persistence.EntityManager;
import jakarta.persistence.LockModeType;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.NoSuchElementException;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.sheet.SheetService;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** The people kept on a sheet. */
@Service
public class PersonService {

    private final PersonRepository people;
    private final PersonPatronRepository patrons;
    private final PersonGradeService grades;
    private final PersonHoldRepository holds;
    private final SheetService sheets;
    private final EntityManager entityManager;
    private final Audit audit;

    public PersonService(PersonRepository people, PersonPatronRepository patrons, PersonGradeService grades,
            PersonHoldRepository holds, SheetService sheets, EntityManager entityManager, Audit audit) {
        this.people = people;
        this.patrons = patrons;
        this.grades = grades;
        this.holds = holds;
        this.entityManager = entityManager;
        this.sheets = sheets;
        this.audit = audit;
    }

    /** The sheet's people in the order they were added. */
    public List<Person> list(String sheetId) {
        return people.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a person to the sheet; the grade they are given applies from the beginning of time. */
    @Transactional
    public Person add(String sheetId, String user, String name, String grade) {
        sheets.load(sheetId);
        String trimmed = name.trim();
        requireFreeName(sheetId, trimmed, null);
        Person added = people.saveAndFlush(new Person(sheetId, trimmed));
        grades.give(added, grade, null);
        record("PERSON_ADDED", sheetId, user, added, grade);
        return added;
    }

    /** Change a person's name, and give them the grade from a date (blank takes the sheet's today),
     *  keeping the grades already given, from an editor that loaded the given version of them. A
     *  blank from-date with the grade in force on the sheet's today gives no grade. */
    @Transactional
    public Person update(String sheetId, String user, Long id, long version, String name, String grade,
            LocalDate gradeFrom) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        if (person.getVersion() != version) {
            throw new StalePersonException(person);
        }
        String trimmed = name.trim();
        requireFreeName(sheetId, trimmed, id);
        person.setName(trimmed);
        LocalDate today = sheets.today(sheetId);
        if (gradeFrom != null || !grade.equals(grades.gradeOn(id, today))) {
            grades.give(person, grade, gradeFrom != null ? gradeFrom : today);
            // A grade given changes the person, so an editor that loaded them before is stale.
            entityManager.lock(person, LockModeType.PESSIMISTIC_FORCE_INCREMENT);
        }
        Person saved = people.saveAndFlush(person);
        record("PERSON_EDITED", sheetId, user, saved, grades.gradeOn(id, today));
        return saved;
    }

    /** Retire a person from a date; a missing date takes the sheet's today. */
    @Transactional
    public Person retire(String sheetId, String user, Long id, LocalDate from) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        person.setRetiredFrom(on);
        Person saved = people.saveAndFlush(person);
        audit.recordOnCommit("PERSON_RETIRED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " from=" + on);
        return saved;
    }

    /** Put a hold on a person from a date (a missing date takes the sheet's today) to an optional
     *  to-date, keeping the holds they have; refused when the to-date is before the from-date. */
    @Transactional
    public Person hold(String sheetId, String user, Long id, LocalDate from, LocalDate to) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        LocalDate on = from != null ? from : sheets.today(sheetId);
        if (to != null && to.isBefore(on)) {
            throw new HoldRefusedException("The hold's to-date " + to + " is before its from-date " + on);
        }
        holds.saveAndFlush(new PersonHold(sheetId, id, on, to));
        audit.recordOnCommit("PERSON_HELD sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " from=" + on);
        return person;
    }

    /** Each person's holds on the sheet, in the order they were put on, by person id; a person with
     *  none is absent. */
    public Map<Long, List<PersonHold>> holds(String sheetId) {
        return holds.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(PersonHold::getPersonId));
    }

    /** A person's holds, in the order they were put on. */
    public List<PersonHold> holds(Long personId) {
        return holds.findByPersonIdOrderByIdAsc(personId);
    }

    /** Each person's patron ids on the sheet, in the order they were named, by person id; a person
     *  with none is absent. */
    public Map<Long, List<Long>> patronIds(String sheetId) {
        return patrons.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.groupingBy(PersonPatron::getPersonId,
                        Collectors.mapping(PersonPatron::getPatronId, Collectors.toList())));
    }

    /** A person's patron ids, in the order they were named. */
    public List<Long> patronIds(Long personId) {
        return patrons.findByPersonIdOrderByIdAsc(personId).stream().map(PersonPatron::getPatronId).toList();
    }

    /** Name another person on the sheet as a person's patron; refused for the person themselves and
     *  for someone already their patron. */
    @Transactional
    public Person addPatron(String sheetId, String user, Long id, Long patronId) {
        Person person = people.findByIdAndSheetId(id, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + id + " on sheet " + sheetId));
        Person patron = people.findByIdAndSheetId(patronId, sheetId)
                .orElseThrow(() -> new NoSuchElementException("No person " + patronId + " on sheet " + sheetId));
        if (person.getId().equals(patron.getId())) {
            throw new PatronRefusedException(person.getName() + " cannot be their own patron");
        }
        if (patrons.existsByPersonIdAndPatronId(person.getId(), patron.getId())) {
            throw new PatronRefusedException(patron.getName() + " is already a patron of " + person.getName());
        }
        patrons.saveAndFlush(new PersonPatron(sheetId, person.getId(), patron.getId()));
        audit.recordOnCommit("PATRON_ADDED sheet=" + sheetId + " by=" + user + " name=" + person.getName()
                + " patron=" + patron.getName());
        return person;
    }

    private void record(String event, String sheetId, String user, Person person, String grade) {
